GraphQL controls the API schema, field selection, validation, and resolver execution; PostgreSQL, MongoDB, and Neo4j still provide persistence, indexes, transactions, document operations, and graph traversal. If a list query returns many users and each `posts` or `follows` resolver issues its own backend query, the resolver layer creates N+1 work. A request-scoped DataLoader can batch user or post keys and cache repeated loads only for that request.

The completed `projector.py` replays Kafka from the partition's low watermark, rebuilds two PostgreSQL projections and one MongoDB projection, and prints a consistent snapshot:

```python
from __future__ import annotations

import json
import os

import psycopg
from confluent_kafka import Consumer, TopicPartition
from psycopg.rows import dict_row
from pymongo import MongoClient


KAFKA_BOOTSTRAP_SERVERS = os.environ["KAFKA_BOOTSTRAP_SERVERS"]
KAFKA_TOPIC = os.environ["KAFKA_TOPIC"]
POSTGRES_DSN = os.environ["POSTGRES_DSN"]
MONGO_URL = os.environ["MONGO_URL"]
MONGO_DB = os.environ["MONGO_DB"]


def read_events() -> list[dict]:
    consumer = Consumer(
        {
            "bootstrap.servers": KAFKA_BOOTSTRAP_SERVERS,
            "group.id": "order-projection-rebuild",
            "enable.auto.commit": False,
        }
    )
    try:
        partition = TopicPartition(KAFKA_TOPIC, 0)
        low, high = consumer.get_watermark_offsets(partition, timeout=10)
        consumer.assign([TopicPartition(KAFKA_TOPIC, 0, low)])

        events: list[dict] = []
        while len(events) < high - low:
            message = consumer.poll(10.0)
            if message is None:
                raise TimeoutError("timed out while replaying Kafka")
            if message.error():
                raise RuntimeError(message.error())
            events.append(json.loads(message.value()))
        return events
    finally:
        consumer.close()


def rebuild_views(events: list[dict]) -> None:
    mongo = MongoClient(MONGO_URL)
    customer_spend = mongo[MONGO_DB].customer_spend_view

    try:
        with psycopg.connect(POSTGRES_DSN) as postgres:
            postgres.execute("TRUNCATE orders_view, daily_revenue_view")
            customer_spend.delete_many({})

            for event in events:
                event_type = event["event_type"]
                total = event["total"]

                if event_type == "OrderPlaced":
                    postgres.execute(
                        """
                        INSERT INTO orders_view (
                          order_id, customer_id, status, total, day
                        )
                        VALUES (%s, %s, 'placed', %s, %s)
                        ON CONFLICT (order_id) DO UPDATE SET
                          customer_id = EXCLUDED.customer_id,
                          status = EXCLUDED.status,
                          total = EXCLUDED.total,
                          day = EXCLUDED.day
                        """,
                        (
                            event["order_id"],
                            event["customer_id"],
                            total,
                            event["day"],
                        ),
                    )
                    delta = total
                elif event_type == "OrderCancelled":
                    result = postgres.execute(
                        """
                        UPDATE orders_view
                        SET status = 'cancelled'
                        WHERE order_id = %s
                        """,
                        (event["order_id"],),
                    )
                    if result.rowcount != 1:
                        raise ValueError(
                            f"cannot cancel unknown order {event['order_id']}"
                        )
                    delta = -total
                else:
                    raise ValueError(f"unknown event type: {event_type}")

                postgres.execute(
                    """
                    INSERT INTO daily_revenue_view (day, net_revenue)
                    VALUES (%s, %s)
                    ON CONFLICT (day) DO UPDATE SET
                      net_revenue = daily_revenue_view.net_revenue
                                    + EXCLUDED.net_revenue
                    """,
                    (event["day"], delta),
                )
                customer_spend.update_one(
                    {"customer_id": event["customer_id"]},
                    {
                        "$setOnInsert": {"customer_id": event["customer_id"]},
                        "$inc": {"net_spend": delta},
                    },
                    upsert=True,
                )
    finally:
        mongo.close()


def snapshot() -> dict:
    with psycopg.connect(POSTGRES_DSN, row_factory=dict_row) as postgres:
        orders = list(
            postgres.execute(
                """
                SELECT order_id, customer_id, status, total, day::text AS day
                FROM orders_view
                ORDER BY order_id
                """
            )
        )
        revenue = list(
            postgres.execute(
                """
                SELECT day::text AS day, net_revenue
                FROM daily_revenue_view
                ORDER BY day
                """
            )
        )

    mongo = MongoClient(MONGO_URL)
    customers = list(
        mongo[MONGO_DB].customer_spend_view.find(
            {}, {"_id": 0, "customer_id": 1, "net_spend": 1}
        ).sort("customer_id", 1)
    )
    mongo.close()
    return {"orders": orders, "daily_revenue": revenue, "customer_spend": customers}


def main() -> None:
    events = read_events()
    rebuild_views(events)
    print(json.dumps({"event_count": len(events), "views": snapshot()}, indent=2))


if __name__ == "__main__":
    main()
```

